command:
printf 'package='; dpkg-query -W -f='${Package} ${Version} ${Architecture}
' chatgpt 2>/dev/null || true; printf 'maintainer='; dpkg-query -W -f='${Maintainer}
' chatgpt 2>/dev/null || true; printf 'homepage='; dpkg-query -W -f='${Homepage}
' chatgpt 2>/dev/null || true; printf 'source='; apt-cache policy chatgpt 2>/dev/null | sed -n '1,8p'; printf '%s
' 'desktop:'; grep -E '^(Name|Exec|Icon|StartupWMClass|Categories)=' /usr/share/applications/chatgpt.desktop 2>/dev/null || true; printf '%s
' 'starter:'; grep -E '^(Name|Exec|Icon|StartupWMClass|Categories)=' ~/.local/share/applications/chatgpt-10x-starter.desktop 2>/dev/null || true; printf '%s
' 'procs:'; ps -eo pid=,comm=,args= | grep -Ei '[c]hatgpt|[c]odex' | head -n 15 || true
